def pre(x):
    return And(x >= 0, x <= 9999)

def post(x, r):
    # Candidate k inserts the digit 5 so that exactly k digits of x lie to its right.
    # Candidate value: (x // 10^k) * 10^(k+1) + 5 * 10^k + (x % 10^k).
    # Position k is possible only if x has at least k digits:
    #   k = 0, 1 always (x = 0 has one digit); k = 2 needs x >= 10; k = 3 needs x >= 100; k = 4 needs x >= 1000.
    cands = []
    for k in range(5):
        p = 10 ** k
        c = (x / p) * (10 * p) + 5 * p + (x % p)
        if k <= 1:
            valid = x >= 0
        else:
            valid = x >= 10 ** (k - 1)
        cands.append((valid, c))

    # r must be one of the valid candidates, and at least as large as every valid candidate.
    is_candidate = Or([And(v, r == c) for v, c in cands])
    is_max = And([Implies(v, r >= c) for v, c in cands])
    return And(is_candidate, is_max)
